//! Shared Win32 helpers. Contract-owned; W2.0 sensors call these and do not edit this file.

use std::marker::PhantomData;
use std::path::Path;

use windows::core::{Owned, PWSTR};
use windows::Win32::Foundation::HWND;
use windows::Win32::System::Com::{CoInitializeEx, CoUninitialize, COINIT_MULTITHREADED};
use windows::Win32::System::Threading::{
    OpenProcess, QueryFullProcessImageNameW, PROCESS_NAME_WIN32, PROCESS_QUERY_LIMITED_INFORMATION,
};
use windows::Win32::System::WinRT::{RoInitialize, RoUninitialize, RO_INIT_MULTITHREADED};
use windows::Win32::UI::WindowsAndMessaging::{
    GetClassNameW, GetForegroundWindow, GetWindowTextW, GetWindowThreadProcessId,
};

/// WinRT MTA init for the thread that constructs it. Not `Send`.
#[must_use = "uninitializes WinRT on drop"]
pub struct WinRtGuard {
    _thread: PhantomData<*const ()>,
}

impl WinRtGuard {
    pub fn mta() -> windows::core::Result<Self> {
        // SAFETY: the sensor thread calls this before any WinRT use. S_FALSE is Ok and Drop balances it.
        unsafe { RoInitialize(RO_INIT_MULTITHREADED)? };
        Ok(Self {
            _thread: PhantomData,
        })
    }
}

impl Drop for WinRtGuard {
    fn drop(&mut self) {
        // SAFETY: mta() returned Ok, including S_FALSE, so this thread owes one RoUninitialize.
        unsafe { RoUninitialize() }
    }
}

/// COM MTA init for the thread that constructs it. Not `Send`.
#[must_use = "uninitializes COM on drop"]
pub struct ComGuard {
    _thread: PhantomData<*const ()>,
}

impl ComGuard {
    pub fn mta() -> windows::core::Result<Self> {
        // SAFETY: the sensor thread calls this before any COM use. HRESULT::ok maps S_FALSE to Ok.
        unsafe { CoInitializeEx(None, COINIT_MULTITHREADED).ok()? };
        Ok(Self {
            _thread: PhantomData,
        })
    }
}

impl Drop for ComGuard {
    fn drop(&mut self) {
        // SAFETY: mta() returned Ok, including S_FALSE, so this thread owes one CoUninitialize.
        unsafe { CoUninitialize() }
    }
}

pub struct ForegroundWindow {
    pub hwnd: HWND,
    pub pid: u32,
    pub exe_name: Option<String>,
    pub title: String,
    pub class: String,
}

pub fn foreground() -> Option<ForegroundWindow> {
    // SAFETY: user32 queries the current desktop. A null HWND is rejected before the buffers are read.
    unsafe {
        let hwnd = GetForegroundWindow();
        if hwnd.is_invalid() {
            return None;
        }
        let mut pid = 0u32;
        if GetWindowThreadProcessId(hwnd, Some(&mut pid)) == 0 || pid == 0 {
            return None;
        }
        let mut title_buf = [0u16; 512];
        let title_len = GetWindowTextW(hwnd, &mut title_buf);
        let mut class_buf = [0u16; 256];
        let class_len = GetClassNameW(hwnd, &mut class_buf);
        Some(ForegroundWindow {
            hwnd,
            pid,
            exe_name: exe_name(pid),
            title: String::from_utf16_lossy(&title_buf[..title_len.max(0) as usize]),
            class: String::from_utf16_lossy(&class_buf[..class_len.max(0) as usize]),
        })
    }
}

pub fn is_own_pid(pid: u32) -> bool {
    pid == std::process::id()
}

fn exe_name(pid: u32) -> Option<String> {
    let path = exe_path(pid).ok()?;
    Path::new(&path)
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
}

fn exe_path(pid: u32) -> windows::core::Result<String> {
    // SAFETY: OpenProcess is owned by `Owned`, which closes the handle on every return path.
    // The buffer is valid for `len` characters and the API writes a NUL-terminated name into it.
    unsafe {
        let handle = Owned::new(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid)?);
        let mut buf = [0u16; 1024];
        let mut len = buf.len() as u32;
        QueryFullProcessImageNameW(
            *handle,
            PROCESS_NAME_WIN32,
            PWSTR(buf.as_mut_ptr()),
            &mut len,
        )?;
        Ok(String::from_utf16_lossy(&buf[..len as usize]))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn own_pid_matches_this_process() {
        assert!(is_own_pid(std::process::id()));
        assert!(!is_own_pid(0));
    }
}
